mapper.select:
SELECT ms.id, ms.patient_id, ms.scheme_id, ms.doctor_name, ms.status, ms.create_time, ms.end_time, ms.create_date, p.name as patient_name, p.gender, p.birth_date, p.medical_record_no as archive_no, p.disease_type FROM medical_scheme ms INNER JOIN patient p ON ms.patient_id = p.id
AND ms.create_time >= #{query.startTime}
AND ms.create_time <= #{query.endTime}
AND ms.create_date >= #{query.startDate}
AND ms.create_date <= #{query.endDate}
AND p.disease_type = #{query.diseaseType}
AND ms.doctor_name LIKE CONCAT('%', #{query.doctorName}, '%')
AND (p.name LIKE CONCAT('%', #{query.searchKeyword}, '%') OR p.medical_record_no LIKE CONCAT('%', #{query.searchKeyword}, '%'))
AND ms.status = #{query.status}
ORDER BY ms.create_time DESC
